    { label: "単独盗塁", noMove: false, aim: "変化球カウントはスタートが切りやすい。打者に注文をつけず走者だけで進む。", ura: "外されたら終わり。エンドランと違い打者が守ってくれない。" },
    { label: "そのまま打たせる", noMove: true, aim: "2-1は打者有利。狙い球を絞らせて普通に勝負するのが一番自然。", ura: "ゴロなら併殺の形は残ったまま。好条件のカウントを作戦に使わないまま終わる可能性。" },
    { label: "待て", noMove: false, aim: "抜け球ならボール。3-1になれば四球も見えて、次のカウントはさらに有利。", ura: "ストライクを置きに来たら1球損。打者の打ち気とのバランスが難しい。" }
