        { label: "打たせる（サイン解除）", aim: "動くと見せて動かない。相手の警戒を空回りさせ、打者は2-2の勝負に集中。", ura: "併殺の形は残る。ここまでの駆け引きが何も生まないまま終わる可能性もある。" }
