    { label: "正面から勝負", noMove: true, aim: "逃げずに最強の打者を最強の球で抑えにいく。抑えれば流れは完全にこちら。", ura: "3打数3安打の事実は重い。単打1本で同点の場面で、確率の悪い勝負を選ぶ形かもしれない。" },
    { label: "くさい所だけ攻めて、結果四球OK", noMove: false, aim: "ボールゾーンの変化球中心に、打ち気に来たら儲けもの。歩かせても計算どおりという柔らかい設計。", ura: "「歩かせてもいい」は投手には難しい注文で、中途半端に甘く入るのが典型的な裏目。" },
    { label: "外野を深めにして勝負", noMove: false, aim: "長打（＝逆転圏）だけ消して勝負する。単打の同点は許容する割り切り。", ura: "前に落ちる打球が増える。同点は「許容した失点」と割り切れるか。" }
