      grow: ["伝令の言葉は1つに絞る（複数の指示は残らない）。「低めだけ」「フォース確認だけ」──何を言わないかまで設計する。", "ゆくゆくは捕手・内野だけで間を作れるチームへ。伝令は文化を作る途中の道具。"]
