    { label: "取っておく", noMove: true, aim: "投手はまだ粘れている。最後の1回は「投手交代を伴う場面」や「サヨナラのピンチ」のために温存する。", ura: "温存したまま今崩れたら本末転倒。「使わなかった資源」は一番悔いが残る。" },
    { label: "捕手をマウンドに行かせる", noMove: false, aim: "野手が集まる形で間を作る（規定の扱いは要確認）。伝令を使わず似た効果を狙う。", ura: "頻発すると試合遅延を注意されうる。捕手に「何を言うか」が委ねられ、質は保証されない。" },
    { label: "ベンチから捕手にサインで方針だけ伝える", noMove: false, aim: "「全部低め・歩かせてもいい」等の方針をサインで渡し、間は作らず整理だけする。", ura: "間を作る効果はゼロ。不安そうな捕手の顔は変わらないかもしれない。" }
