    { label: "前進守備で止血", noMove: false, aim: "これ以上1点もやらない構え。ゴロは本塁で刺す。", ura: "崩れかけの内野に一番難しいタッチプレーを求める。抜かれれば2点ずつ入る隊形でもある。" },
    { label: "中間守備", noMove: false, aim: "強いゴロはアウト優先、詰まったゴロは本塁と、打球で選ぶ。", ura: "判断の難度は最も高い。迷いが一番事故を生む隊形でもある。" },
    { label: "伝令＋定位置", noMove: false, aim: "間を作って「1点OK・近い塁・フォース確認」を全員の声で確認してから、割り切りの守備へ。", ura: "伝令を1回使う。" }
