    { label: "投手交代", noMove: false, aim: "四球の連鎖は続くと読み、傷が開く前に代える。", ura: "満塁・一死という最悪の場面を2番手に背負わせる。うちの2番手にその経験値はあるか。" },
    { label: "バッテリーに任せる", noMove: true, aim: "介入せず、捕手のリードと投手の立て直しに委ねる。", ura: "「置きに行く」が始まった投手は、自力では戻れないことが多い。押し出しか痛打が現実になってから動くことになる。" },
    { label: "中間守備でゲッツー狙いを宣言", noMove: false, aim: "「ゴロならゲッツーでチェンジ」の絵を全員に見せ、守備から投手を支える。", ura: "本塁フォースの意識が薄れると、詰まったゴロで本塁を逃す。二兎の混乱もありうる。" }
