    teigen: [
      { text: "ベンチワークの実務は「観察係を決めて情報を集め、作戦に使う」こと。声の量は精神論でなく、仕事の有無で決まる面が大きいとされる。", evidence: "coach-consensus", levelNote: "初心者ほど「何を見ればいいか」を知らないので黙る。見る対象（クイックの秒数・捕手の肩・三塁手のチャージ）を具体的に渡すだけで、ベンチは急に喋り始める。" }
    ],
    safety: null,
    voice: "「次の回、先頭が出たら仕掛けるぞ。そのために今から集めてくれ──1・3番はクイックの速さ、2番は捕手の肩な」",
    refs: ["戦術・状況判断/09-攻撃の戦術", "指導法/03-教え方のコツ"]
