    teigen: [
      { text: "中間守備に対する三塁走者は、内野ゴロでの生還可否を「打球の速さと方向」でその都度判断する必要があるとされる。前進守備・定位置守備ほど答えが単純ではない、中間ならではの難しさがある。", evidence: "coach-consensus", levelNote: "三塁コーチの目測経験がものを言う。日頃から様々な守備位置を想定した走塁練習をしているかで判断の精度が変わる。" },
      { text: "ライナーの併殺は、三塁走者が飛び出した直後に最も起こりやすい事故の一つとされる。「ライナーバック」の徹底は、ゴロゴーの積極策と並ぶ基本の型。", evidence: "coach-consensus", levelNote: "経験の浅いチームほどライナーバックの徹底を優先する価値が高い。併殺の事故は取れたはずの1点以上の被害を生むことがある。" }
    ],
    safety: null,
