    { label: "強攻(サインなし)", noMove: true, aim: "無死二塁という好機そのものを縮めない。長打が出れば1点どころか一気に複数点も見える。", ura: "併殺こそ出にくい形だが、内野ゴロで二塁走者が三塁止まりになれば、結局バントと同じ一死三塁を「アウトを払わず」作れなかった悔いが残る。" },
    { label: "初球だけ様子を見る(1ストライクまで待て)", noMove: false, aim: "無死二塁の価値をすぐには手放さず、まず1球相手投手の立ち上がりを見極めてから作戦を決める。", ura: "様子見の間にカウントが不利になれば、バントも強攻も選択の自由度が減る。" }
