    { label: "ブルペンを作りながら続投", noMove: false, aim: "今すぐは代えず、2番手の準備だけ進める。次の一打・一四球が出た瞬間に動ける形にしておく。", ura: "準備していること自体が投手に伝わり、間合いや表情に影響することがある。結局ズルズル引っ張る一番悪い形になる危険も残る。" },
    { label: "伝令で間を作り様子を見る", noMove: false, aim: "交代の判断を1球先送りにし、投手の呼吸と守備の集中を整える時間を作る。", ura: "伝令の回数は限られている。ここで使うと、本当に必要な終盤の場面で使えなくなる。" }
