    { label: "代打は温存し、次の好機に回す", noMove: false, aim: "先頭のこの1打席では動かず、後ろの打者が出塁したときの代打起用に賭ける。守備の穴を先送りにできる可能性を残す。", ura: "温存している間に先頭が凡退すると、代打を使う好機自体が来ないまま終わることもある。" }
