    { label: "下位打線をそのまま行かせる", noMove: true, aim: "打順の流れに任せ、切り札は温存する。8番・9番にもこの場面を経験させる。", ura: "期待値としては代打より低い可能性がある。何もしないまま試合が終わるリスクを承知で選ぶ形になる。" }
