      { text: "伝令を使い切った後の手当ては、守備位置の調整と継投の2つが主な選択肢とされる。球数がかさんでいる投手には継投がより優先されやすい。", evidence: "coach-consensus", levelNote: "投手が1人しかいないチームでは継投の選択肢自体が乏しく、守備位置の調整だけで最少失点を目指す設計も現実的な解になる。" }
